import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createIsolatedAcquirer, externalTransport } from './isolated-acquirer.mjs';
import { evaluate, render } from '../wsc-vs1/engine.mjs';

const root = path.dirname(fileURLToPath(import.meta.url));
const fixture = JSON.parse(fs.readFileSync(path.join(root, '..', 'wsc-vs1', 'fixtures', 'synthetic-protected.json'), 'utf8'));
const url = 'https://example-protected.test/';
const diagnosis = () => ({ ...structuredClone(fixture), targetUrl: url, mailDomain: 'example-protected.test', checkedAt: '2026-10-25T00:00:00.000Z' });
const resolve = () => ['93.184.216.34'];
const response = (overrides = {}) => ({ remoteAddress: '93.184.216.34', responseBytes: 512, bodyChunks: [new Uint8Array(512)], diagnosis: diagnosis(), ...overrides });
const ok = createIsolatedAcquirer({ resolve, probe: async () => response() });
const result = await ok({ url, mailDomain: 'example-protected.test' });
assert.equal(result.targetUrl, url); assert.equal(result.dns.dmarc.lookupStatus, 'FOUND');
let normalSignal; const completed = await createIsolatedAcquirer({ resolve, probe: async ({ signal }) => { normalSignal = signal; return response(); } })({ url, mailDomain: 'example-protected.test' });
assert.equal(completed.targetUrl, url); assert.equal(normalSignal.aborted, false, 'normal completion clears its timeout without cancellation');
const invalidTls = { ...JSON.parse(fs.readFileSync(path.join(root, '..', 'wsc-vs1', 'fixtures', 'synthetic-gaps.json'), 'utf8')), targetUrl: url, mailDomain: 'example-protected.test', checkedAt: '2026-10-25T00:00:00.000Z' };
const tlsFailure = await createIsolatedAcquirer({ resolve, probe: async () => response({ responseBytes: 1, bodyChunks: [new Uint8Array(1)], diagnosis: invalidTls }) })({ url, mailDomain: 'example-protected.test' });
assert.equal(tlsFailure.tls.status, 'VALIDATION_FAILED'); assert.equal(tlsFailure.dns.dmarc.lookupStatus, 'NO_RECORD');
const noMail = await ok({ url });
assert.equal(noMail.mailDomain, null); assert.equal(noMail.dns.spf.error, 'MAIL_DOMAIN_UNSPECIFIED');
const options = { rulesPath: path.join(root, '..', 'wsc-vs1', 'rules.json'), explanationsPath: path.join(root, '..', 'wsc-vs1', 'explanations.json') };
const noMailReport = evaluate(noMail, options); const noMailHtml = render(noMailReport, { name: 'Synthetic', headOffice: 'Tokyo', url });
assert.ok(!noMailReport.findings.some(item => /^(SPF|DMARC)/.test(item.id))); assert.ok(!noMailHtml.includes('メールの送信元を示す設定があります'));
await assert.rejects(() => ok({ url, mailDomain: 'not a domain' }), /MAIL_DOMAIN_INVALID/);
await assert.rejects(() => createIsolatedAcquirer({ resolve, maxResponseBytes: 100, probe: async () => response({ responseBytes: 101, bodyChunks: [new Uint8Array(100)] }) })({ url, mailDomain: 'example-protected.test' }), /HTTP_RESPONSE_DECLARED_SIZE_LIMIT/);
const boundary = await createIsolatedAcquirer({ resolve, maxResponseBytes: 100, probe: async () => response({ responseBytes: 100, bodyChunks: [new Uint8Array(40), new Uint8Array(60)] }) })({ url, mailDomain: 'example-protected.test' });
assert.equal(boundary.targetUrl, url);
let bodyAborted = false;
await assert.rejects(() => createIsolatedAcquirer({ resolve, maxResponseBytes: 100, probe: async ({ signal }) => { signal.addEventListener('abort', () => { bodyAborted = true; }); return response({ responseBytes: 100, bodyChunks: [new Uint8Array(60), new Uint8Array(41)] }); } })({ url, mailDomain: 'example-protected.test' }), /HTTP_RESPONSE_BODY_SIZE_LIMIT/);
assert.equal(bodyAborted, true, 'body limit notifies the probe cancellation signal');
let timeoutAborted = false;
await assert.rejects(() => createIsolatedAcquirer({ resolve, timeoutMs: 1, probe: async ({ signal }) => new Promise(resolve => signal.addEventListener('abort', () => { timeoutAborted = true; resolve(response()); })) })({ url }), /ACQUISITION_TIMEOUT/);
assert.equal(timeoutAborted, true, 'timeout notifies the probe cancellation signal');
await assert.rejects(() => createIsolatedAcquirer({ resolve: () => [], probe: async () => ({}) })({ url }), /DNS_NOT_PUBLIC/);
await assert.rejects(() => createIsolatedAcquirer({ resolve: (() => { let count = 0; return () => count++ ? ['93.184.216.35'] : ['93.184.216.34']; })(), probe: async () => response() })({ url }), /DNS_REBIND_DETECTED/);
await assert.rejects(() => createIsolatedAcquirer({ resolve, probe: async () => response({ remoteAddress: '93.184.216.35' }) })({ url }), /CONNECTION_IP_MISMATCH/);
await assert.rejects(() => createIsolatedAcquirer({ resolve, probe: async () => response({ redirectUrl: 'https://other.example/' }) })({ url }), /REDIRECT_REQUIRES_SEPARATE_APPROVAL/);
assert.throws(() => externalTransport(), /EXTERNAL_TRANSPORT_DISABLED_PENDING_APPROVAL/);
console.log('WSC Phase 2B isolated-acquisition tests: PASS');
